import React, { useEffect, useState } from "react";
import { graphql } from "gatsby";
import { AdminLayout } from "../../features/admin/components/AdminLayout";
import { listUsers } from "../../sessionServices/users/usersService";
import { listItinerariesByUser } from "../../sessionServices/itineraries/itinerariesService";
import { listActivitiesByItinerary } from "../../sessionServices/itineraries/activitiesService";
import type { UserProfile, Activity, Itinerary } from "../../features/admin/types";

type ActivityWithId = Activity & { id: string };
type ItineraryWithId = Itinerary & { id: string };

interface ActivityRow {
  itineraryTitle: string;
  activityName: string;
  category?: string;
  costBreakdown: string[];
  cost?: number;
  price?: number;
}

interface UserReport {
  user: UserProfile;
  rows: ActivityRow[];
  totalCost: number;
  totalPrice: number;
}

export default function ReportPage() {
  const [reports, setReports] = useState<UserReport[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      const users = await listUsers();
      const customers = users.filter((u) => u.role === "customer");

      const userReports = await Promise.all(
        customers.map(async (user) => {
          const itineraries: ItineraryWithId[] = await listItinerariesByUser(user.uid);
          const allActivities = await Promise.all(
            itineraries.map((it) =>
              listActivitiesByItinerary(it.id).then((acts) =>
                acts.map((a) => ({ ...a, _itineraryTitle: it.title }))
              )
            )
          );
          const rows: ActivityRow[] = allActivities.flat().map((a) => ({
            itineraryTitle: (a as ActivityWithId & { _itineraryTitle: string })._itineraryTitle,
            activityName: a.name,
            category: a.category,
            costBreakdown: a.costBreakdown ?? [],
            cost: a.cost,
            price: a.price,
          }));
          const totalCost = rows.reduce((s, r) => s + (r.cost ?? 0), 0);
          const totalPrice = rows.reduce((s, r) => s + (r.price ?? 0), 0);
          return { user, rows, totalCost, totalPrice };
        })
      );

      setReports(userReports.filter((r) => r.rows.length > 0));
      setLoading(false);
    }
    load();
  }, []);

  return (
    <AdminLayout title="Cost & Price Report">
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
        </div>
      ) : reports.length === 0 ? (
        <p className="text-sm text-gray-400">No activity data found.</p>
      ) : (
        <div className="space-y-8">
          {reports.map(({ user, rows, totalCost, totalPrice }) => (
            <div key={user.uid} className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
              {/* User header */}
              <div className="border-b border-gray-100 bg-gray-50 px-5 py-3">
                <p className="text-sm font-semibold text-gray-900">{user.fullName}</p>
                <p className="text-xs text-gray-500">{user.email}</p>
              </div>

              {/* Table */}
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-gray-100 text-xs font-medium text-gray-500">
                      <th className="px-5 py-2.5 text-left">Itinerary</th>
                      <th className="px-5 py-2.5 text-left">Activity</th>
                      <th className="px-5 py-2.5 text-left">Category</th>
                      <th className="px-5 py-2.5 text-left">Cost breakdown</th>
                      <th className="px-5 py-2.5 text-right">Cost</th>
                      <th className="px-5 py-2.5 text-right">Price</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {rows.map((row, i) => (
                      <tr key={i} className="hover:bg-gray-50">
                        <td className="px-5 py-2.5 text-xs text-gray-500">{row.itineraryTitle}</td>
                        <td className="px-5 py-2.5 font-medium text-gray-900">{row.activityName}</td>
                        <td className="px-5 py-2.5 text-xs text-gray-500">{row.category ?? "—"}</td>
                        <td className="px-5 py-2.5">
                          {row.costBreakdown.length > 0 ? (
                            <div className="flex flex-wrap gap-1">
                              {row.costBreakdown.map((tag) => (
                                <span key={tag} className="rounded-full bg-gray-100 px-2 py-0.5 text-xs text-gray-600">
                                  {tag}
                                </span>
                              ))}
                            </div>
                          ) : (
                            <span className="text-xs text-gray-300">—</span>
                          )}
                        </td>
                        <td className="px-5 py-2.5 text-right text-xs text-gray-700">
                          {row.cost != null ? `$${row.cost.toFixed(2)}` : "—"}
                        </td>
                        <td className="px-5 py-2.5 text-right text-xs text-gray-700">
                          {row.price != null ? `$${row.price.toFixed(2)}` : "—"}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="border-t-2 border-gray-200 bg-gray-50 font-semibold">
                      <td colSpan={4} className="px-5 py-2.5 text-xs text-gray-600">Total</td>
                      <td className="px-5 py-2.5 text-right text-xs text-gray-900">${totalCost.toFixed(2)}</td>
                      <td className="px-5 py-2.5 text-right text-xs text-gray-900">${totalPrice.toFixed(2)}</td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>
          ))}
        </div>
      )}
    </AdminLayout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
